import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

export default function CustomerPage() {
  const [menu, setMenu] = useState([]);
  const [cart, setCart] = useState([]);
  const [tableNumber, setTableNumber] = useState("");
  const [theme, setTheme] = useState("dark");
  const [font, setFont] = useState("inter");
  const navigate = useNavigate();

  useEffect(() => {
    const savedMenu = JSON.parse(localStorage.getItem("menuData") || "[]");
    const savedTheme = localStorage.getItem("theme") || "dark";
    const savedFont = localStorage.getItem("font") || "inter";
    setMenu(savedMenu);
    setTheme(savedTheme);
    setFont(savedFont);
    document.body.className = `${savedTheme} font-${savedFont}`;
  }, []);

  const addToCart = (item) => {
    setCart([...cart, item]);
  };

  const removeFromCart = (index) => {
    const updated = [...cart];
    updated.splice(index, 1);
    setCart(updated);
  };

  const handleOrder = () => {
    if (!tableNumber || cart.length === 0) return;

    const order = {
      tableNumber,
      items: cart,
      status: "Ausstehend",
    };

    localStorage.setItem("currentOrder", JSON.stringify(order));
    const all = JSON.parse(localStorage.getItem("allOrders") || "[]");
    all.push(order);
    localStorage.setItem("allOrders", JSON.stringify(all));
    setCart([]);
    navigate("/status");
  };

  const total = cart.reduce((sum, item) => sum + (item.price || 0), 0);

  return (
    <div className="min-h-screen p-6">
      <h1 className="text-3xl font-bold mb-6">Digitale Speisekarte</h1>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {menu.map((cat, catIndex) => (
          <div key={catIndex}>
            <h2 className="text-xl font-semibold mb-2">{cat.category}</h2>
            <div className="flex flex-col gap-2">
              {cat.items.map((item, index) =>
                item.available ? (
                  <div key={index} className="flex justify-between items-center bg-gray-800 text-white p-3 rounded">
                    <div>
                      <p className="font-medium">{item.name}</p>
                      <p className="text-sm">{item.price.toFixed(2)} €</p>
                    </div>
                    <button
                      onClick={() => addToCart(item)}
                      className="bg-green-600 hover:bg-green-700 px-3 py-1 rounded text-sm"
                    >
                      Hinzufügen
                    </button>
                  </div>
                ) : null
              )}
            </div>
          </div>
        ))}
      </div>

      <div className="mt-10">
        <h2 className="text-2xl font-bold mb-4">Warenkorb</h2>
        {cart.length === 0 ? (
          <p className="text-gray-400">🛒 Dein Warenkorb ist leer.</p>
        ) : (
          <ul className="mb-4">
            {cart.map((item, index) => (
              <li key={index} className="flex justify-between items-center bg-gray-700 text-white p-2 mb-2 rounded">
                {item.name} – {item.price.toFixed(2)} €
                <button onClick={() => removeFromCart(index)} className="ml-4 text-red-400 hover:text-red-600">
                  Entfernen
                </button>
              </li>
            ))}
          </ul>
        )}

        <p className="font-semibold mb-4">Gesamt: {total.toFixed(2)} €</p>

        <input
          type="text"
          placeholder="Tischnummer eingeben"
          className="p-2 rounded text-black mb-4 block"
          value={tableNumber}
          onChange={(e) => setTableNumber(e.target.value)}
        />

        <button
          disabled={cart.length === 0 || !tableNumber}
          onClick={handleOrder}
          className="bg-blue-600 hover:bg-blue-700 px-6 py-2 rounded text-white disabled:opacity-50"
        >
          Bestellung abschicken
        </button>
      </div>
    </div>
  );
}
